    login_s_login_acknowledged,
    login_s_login_start: LoginSLoginStart,
    login_s_login_plugin_response: LoginSLoginPluginResponse,
    s_attack: SAttack,
    s_block_entity_tag_query: SBlockEntityTagQuery,
    s_bundle_item_selected: SBundleItemSelected,
    s_change_difficulty: SChangeDifficulty,
    s_change_game_mode: SChangeGameMode,
    s_chat_ack: SChatAck,
    s_chat_command: SChatCommand,
    s_chat_command_signed: SChatCommandSigned,
    s_chat_message: SChatMessage,
    s_chunk_batch: SChunkBatch,
    s_click_slot: SClickSlot,
    s_client_command: SClientCommand,
    s_client_information_play: SClientInformationPlay,
    s_client_tick_end,
    s_close_container: SCloseContainer,
    s_command_suggestion: SCommandSuggestion,
    s_configuration_acknowledged,
    s_container_button_click: SContainerButtonClick,
    s_container_slot_state_changed: SContainerSlotStateChanged,
    /// Response to a `CCookieRequest` (play) from the server.
    /// The Notchian (vanilla) server only accepts responses of up to 5 KiB in size.
    s_cookie_response: SCookieResponse,
    s_custom_click_action: SCustomClickAction,
    /// A packet used for custom communication between the client and server.
    ///
    /// This allows mods, plugins, or proxy software to send proprietary data over the standard
    /// Minecraft protocol.
    s_custom_payload: SCustomPayload,
    s_debug_sample_subscription: SDebugSampleSubscription,
    s_debug_subscription_request: SDebugSubscriptionRequest,
    s_edit_book: SEditBook,
    s_entity_tag_query: SEntityTagQuery,
    s_interact: SInteract,
    s_jigsaw_generate: SJigsawGenerate,
    s_keep_alive: SKeepAlive,
    s_lock_difficulty: SLockDifficulty,
    s_move_vehicle: SMoveVehicle,
    s_paddle_boat: SPaddleBoat,
    s_pick_item_from_block: SPickItemFromBlock,
    s_pick_item_from_entity: SPickItemFromEntity,
    s_play_ping_request: SPlayPingRequest,
    s_place_recipe: SPlaceRecipe,
    s_player_abilities: SPlayerAbilities,
    s_player_action: SPlayerAction,
    s_player_command: SPlayerCommand,
    s_set_player_ground: SSetPlayerGround,
    s_player_input: SPlayerInput,
    /// Added in 1.21.4
    s_player_loaded,
    s_player_position: SPlayerPosition,
    s_player_position_rotation: SPlayerPositionRotation,
    s_player_rotation: SPlayerRotation,
    s_player_session: SPlayerSession,
    s_play_pong: SPlayPong,
    s_recipe_book_change_settings: SRecipeBookChangeSettings,
    s_recipe_book_seen_recipe: SRecipeBookSeenRecipe,
    s_rename_item: SRenameItem,
    s_play_resource_pack: SPlayResourcePack,
    s_seen_advancement: SSeenAdvancement,
    s_select_trade: SSelectTrade,
    s_set_beacon: SSetBeacon,
    s_set_command_block: SSetCommandBlock,
    s_set_command_minecart: SSetCommandMinecart,
    s_set_creative_slot: SSetCreativeSlot,
    s_set_game_rule: SSetGameRule,
    s_set_held_item: SSetHeldItem,
    s_set_jigsaw_block: SSetJigsawBlock,
    s_set_structure_block: SSetStructureBlock,
    s_set_test_block: SSetTestBlock,
    s_spectate_entity: SSpectateEntity,
    s_teleport_to_entity: STeleportToEntity,
    s_test_instance_block_action: STestInstanceBlockAction,
    s_update_sign: SUpdateSign,
    s_use_item: SUseItem,
    s_use_item_on: SUseItemOn,
    /// Sent by the client to measure the round-trip time (latency) to the server.
    ///
    /// This is the second part of the Server List Ping (SLP) process
    /// The server should respond with `CPingResponse`.
    status_s_status_ping_request: StatusSStatusPingRequest,
    /// Sent by the client to request the server's current status information.
    ///
    /// This is the first packet sent during the "Status" state.
    /// The server should respond with `CStatusResponse`.
    status_s_status_request,
    unknown,
