pub const ClientboundPacket = union(enum) {
    config_c_config_add_resource_pack: ConfigCConfigAddResourcePack,
    config_c_config_clear_dialog,
    config_c_code_of_conduct: ConfigCCodeOfConduct,
    config_c_config_disconnect: ConfigCConfigDisconnect,
    /// Requests a cookie that was previously stored.
    config_c_cookie_request: ConfigCCookieRequest,
    config_c_config_custom_report_details: ConfigCConfigCustomReportDetails,
    config_c_feature_flags: ConfigCFeatureFlags,
    config_c_finish_config,
    config_c_known_packs: ConfigCKnownPacks,
    config_c_config_ping: ConfigCConfigPing,
    config_c_plugin_message: ConfigCPluginMessage,
    config_c_config_post_effects: ConfigCConfigPostEffects,
    /// Added in 1.20.2
    config_c_registry_data: ConfigCRegistryData,
    config_c_config_remove_resource_pack: ConfigCConfigRemoveResourcePack,
    config_c_config_reset_chat,
    config_c_config_server_links: ConfigCConfigServerLinks,
    config_c_config_show_dialog: ConfigCConfigShowDialog,
    /// Stores some arbitrary data on the client, which persists between server transfers.
    /// The Notchian (vanilla) client only accepts cookies of up to 5 KiB in size.
    config_c_store_cookie: ConfigCStoreCookie,
    config_c_transfer: ConfigCTransfer,
    config_c_update_tags: ConfigCUpdateTags,
    /// Sent by the server to retrieve a previously stored cookie from the client.
    ///
    /// This occurs during the login phase, allowing the server to identify
    /// returning players or retrieve session data stored during a previous visit.
    login_c_login_cookie_request: LoginCLoginCookieRequest,
    /// Sent by the server to reject a login attempt or kick a player during the login phase
    ///
    /// This is used for reasons such as the server being full, the player being banned,
    /// or version mismatches. After this packet is sent, the connection is closed.
    login_c_login_disconnect: LoginCLoginDisconnect,
